using System.Text;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
using ReconciliationPlatform.Core;
using ReconciliationPlatform.Infrastructure;
var b = WebApplication.CreateBuilder(args); b.Services.AddControllers(); b.Services.AddProblemDetails(); b.Services.AddDbContext<ReconciliationDbContext>(o => o.UseSqlServer(b.Configuration.GetConnectionString("Reconciliation") ?? throw new InvalidOperationException("Connection string required."))); b.Services.AddScoped<IReconciliationStore, SqlReconciliationStore>(); b.Services.AddScoped<IngestionService>(); b.Services.AddSingleton(TimeProvider.System); var key = b.Configuration["Jwt:SigningKey"] ?? throw new InvalidOperationException("JWT signing key required."); b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o => o.TokenValidationParameters = new() { ValidateIssuerSigningKey = true, IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)), ValidateIssuer = true, ValidIssuer = b.Configuration["Jwt:Issuer"], ValidateAudience = true, ValidAudience = b.Configuration["Jwt:Audience"], ValidateLifetime = true, RoleClaimType = "role" }); b.Services.AddAuthorizationBuilder().AddPolicy("Ingest", p => p.RequireRole("ReconciliationProducer")).AddPolicy("Operations", p => p.RequireRole("ReconciliationOperator")); b.Services.AddHealthChecks(); var app = b.Build(); app.UseExceptionHandler(); app.UseAuthentication(); app.UseAuthorization(); app.MapControllers(); app.MapHealthChecks("/health"); app.Run(); public partial class Program;
